<script setup lang="ts">
import { reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { post, patch, message } from '../api'
import { useList } from '../useList'
import { useAuth } from '../auth'
import LoadError from '../components/LoadError.vue'
import RoleAccess from '../components/RoleAccess.vue'
const auth=useAuth(),list=useList('/users'),open=ref(false),busy=ref(false),error=ref(''),editing=ref<any>(null)
const roles=useList('/roles'),roleOpen=ref(false)
const form=reactive({username:'',password:'',role:'user'})
function edit(row?:any){editing.value=row||null;Object.assign(form,{username:row?.username||'',password:'',role:row?.role||'user'});error.value='';open.value=true}
async function save(){busy.value=true;error.value='';try{if(!editing.value&&!form.username.trim())throw new Error('请输入账号');if(!editing.value&&!form.password)throw new Error('请输入密码');if(form.password&&(new TextEncoder().encode(form.password).length<12||new TextEncoder().encode(form.password).length>72))throw new Error('密码长度需为12–72字节');if(editing.value){await patch(`/users/${editing.value.id}`,{role:form.role,...(form.password?{password:form.password}:{})})}else await post('/users',form);form.password='';open.value=false;ElMessage.success('用户已保存');await list.load();if(editing.value?.id===auth.user?.id)await auth.refresh()}catch(e){error.value=message(e)}finally{busy.value=false}}
async function toggle(row:any){try{await ElMessageBox.confirm(`${row.enabled?'停用':'启用'}「${row.username}」？${row.enabled?'停用后 Web 和 Gateway 访问将失效。':''}`,'修改用户状态',{type:'warning'});await patch(`/users/${row.id}`,{enabled:!row.enabled});await list.load();ElMessage.success('状态已更新')}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(message(e))}}
</script>
<template><section class="panel"><div class="panel-toolbar"><div><h2>组织成员 <span class="count-badge">{{list.total.value}}</span></h2><p>管理身份控制平台操作；MCP 使用角色控制可调用的服务和工具，多个角色权限取并集。普通成员未分配角色时不能调用 MCP。</p></div><div class="toolbar-actions"><el-button @click="list.load();roles.load()">刷新</el-button><el-button @click="roles.load();roleOpen=true">角色管理</el-button><el-button type="primary" @click="edit()">创建用户</el-button></div></div><LoadError :error="list.error.value||roles.error.value" @retry="list.load();roles.load()"/><el-table :data="list.items.value" v-loading="list.loading.value"><el-table-column label="账号" min-width="220"><template #default="{row}"><div class="service-name"><span class="avatar">{{row.username.slice(0,1).toUpperCase()}}</span><strong>{{row.username}}</strong><el-tag v-if="row.id===auth.user?.id" size="small" type="info">当前账号</el-tag></div></template></el-table-column><el-table-column label="管理身份"><template #default="{row}">{{row.role==='admin'?'管理员':'普通成员'}}</template></el-table-column><el-table-column label="MCP 使用角色" min-width="200"><template #default="{row}"><span v-if="row.role==='admin'">全部 MCP（管理员）</span><template v-else><el-tag v-for="role in roles.items.value.filter(x=>x.user_ids.includes(row.id))" :key="role.id" style="margin:2px">{{role.name}}</el-tag><span v-if="!roles.items.value.some(x=>x.user_ids.includes(row.id))" class="muted">未授权</span></template></template></el-table-column><el-table-column label="状态"><template #default="{row}"><el-tag :type="row.enabled?'success':'info'" round>{{row.enabled?'已启用':'已停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="180"><template #default="{row}"><el-button text type="primary" @click="edit(row)">编辑</el-button><el-button text :type="row.enabled?'danger':'success'" @click="toggle(row)">{{row.enabled?'停用':'启用'}}</el-button></template></el-table-column></el-table></section><el-dialog v-model="open" :title="editing?'编辑用户':'创建用户'" width="480px" @closed="form.password=''"><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-form label-position="top" @submit.prevent="save"><el-form-item label="账号"><el-input v-model="form.username" :disabled="!!editing" autocomplete="off"/></el-form-item><el-form-item :label="editing?'重置密码（留空保留）':'初始密码'"><el-input v-model="form.password" type="password" show-password autocomplete="new-password" placeholder="12–72字节"/></el-form-item><el-form-item label="管理身份"><el-select v-model="form.role"><el-option label="普通成员" value="user"/><el-option label="管理员" value="admin"/></el-select></el-form-item><p class="muted">重置密码会使该用户原 Web 会话失效。客户端 Token 需单独撤销。</p></el-form><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="busy" @click="save">保存用户</el-button></template></el-dialog><RoleAccess v-if="roleOpen" v-model="roleOpen" :roles="roles.items.value" :users="list.items.value" @changed="roles.load()"/></template>
